"""Typed results with JSON, Markdown and plain-text reporting."""
from __future__ import annotations

from dataclasses import asdict, dataclass, field, is_dataclass
import json
from pathlib import Path
from typing import Any

import numpy as np

DISCLAIMER = (
    "SpectralAudit measures spectral patterns, not AI authorship. Its findings do not "
    "constitute proof that a recording was generated by artificial intelligence."
)


def _json_default(value: Any) -> Any:
    if is_dataclass(value) and not isinstance(value, type):
        return asdict(value)
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Path):
        return str(value)
    raise TypeError(f"Cannot serialize {type(value).__name__}")



def _display(value: Any) -> str:
    if isinstance(value, str):
        return value.replace("\n", " ").replace("\r", " ")
    return json.dumps(value, default=_json_default, ensure_ascii=False, allow_nan=False)


def _lines(obj: dict[str, Any], *, markdown: bool, level: int = 0) -> list[str]:
    lines: list[str] = []
    prefix = "  " * level
    for key, value in obj.items():
        key = str(key).replace("\n", " ")
        if isinstance(value, dict):
            lines.append(f"{prefix}- **{key}**:" if markdown else f"{prefix}{key}:")
            lines.extend(_lines(value, markdown=markdown, level=level + 1))
        else:
            result = _display(value)
            if markdown:
                result = result.replace("\\", "\\\\").replace("\x60", "\\\x60")
                lines.append(f"{prefix}- **{key}**: \x60{result}\x60")
            else:
                lines.append(f"{prefix}{key}: {result}")
    return lines


def format_payload(payload: dict[str, Any], *, format: str = "text",
                   title: str = "SpectralAudit report") -> str:
    """Render the full findings without truncation or HTML."""
    if format not in ("text", "markdown"):
        raise ValueError("format must be 'text' or 'markdown'")
    md = format == "markdown"
    lines = [f"# {title}" if md else title.upper(), ""]
    if "version" in payload:
        lines.extend([f"**Version:** {payload['version']}" if md
                      else f"Version: {payload['version']}", ""])
    if "interpretation" in payload:
        lines.extend(["## Interpretation" if md else "INTERPRETATION",
                      str(payload["interpretation"]), ""])
    for section in ("metadata", "findings", "results"):
        data = payload.get(section)
        if data is None:
            continue
        lines.append(f"## {section.title()}" if md else section.upper())
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(value, dict) and section == "findings":
                    lines.append(f"### {key.replace('_', ' ').title()}" if md
                                 else f"  {key.upper()}")
                    lines.extend(_lines(value, markdown=md, level=0 if md else 2))
                else:
                    lines.extend(_lines({key: value}, markdown=md))
        else:
            lines.extend(_lines({section: data}, markdown=md))
        lines.append("")
    if "limitations" in payload:
        lines.append("## Limitations" if md else "LIMITATIONS")
        lines.extend(f"- {v}" for v in payload["limitations"])
        lines.append("")
    lines.extend(["## Scientific note" if md else "SCIENTIFIC NOTE", DISCLAIMER, ""])
    return "\n".join(lines)


@dataclass
class AuditReport:
    """Conservative observations, without an inferred AI origin probability."""

    metadata: dict[str, Any]
    findings: dict[str, Any]
    limitations: list[str] = field(default_factory=list)
    interpretation: str = "Origin inconclusive: spectral characteristics do not establish provenance."
    version: str = "0.3.0"

    def as_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, path: str | Path) -> Path:
        target = Path(path)
        target.write_text(json.dumps(self.as_dict(), indent=2, default=_json_default, allow_nan=False), encoding="utf-8")
        return target


    def as_markdown(self) -> str:
        return format_payload(self.as_dict(), format="markdown")

    def as_text(self) -> str:
        return format_payload(self.as_dict(), format="text")

    def to_markdown(self, path: str | Path) -> Path:
        target = Path(path)
        target.write_text(self.as_markdown(), encoding="utf-8")
        return target

    def to_text(self, path: str | Path) -> Path:
        target = Path(path)
        target.write_text(self.as_text(), encoding="utf-8")
        return target
